        8,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos III.32</em> <small>(c. 350 AD)</small><p>&#x27;Which none of the princes of this world knew: for had they known it, they would not have crucified the Lord of glory&#x27; — Athanasius marks ton kyrion tēs doxēs estaurōsan (they crucified the Lord of glory) as the COMMUNICATIO-IDIOMATUM Pauline-anchor. The crucified-one IS the Lord-of-glory — the divine-glory-Bearer is the same-Person who suffered on the cross, predicated by the single-Person-of-the-incarnate-Word. The Arian/Nestorian scheme cannot account for this language without making it metaphorical; Athanasian-Pauline Christology takes it as ontological. Tewahedo Holy-Friday-hymnody (Maḫrāya-Sǝqlät) cites 1 Cor 2:8 as the kyrios-of-glory-crucified Miaphysite-anchor.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
