        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §13</em> <small>(c. 350 AD)</small><p>&#x27;And did all drink the same spiritual drink: for they drank of that spiritual Rock that followed them: and that Rock was Christ&#x27; — Athanasius marks hē petra de ēn ho Christos (the Rock was Christ) as the Pauline-pre-incarnation-presence prooftext. The same Word who became-incarnate-in-the-fullness-of-time was already-present in the Exodus-economy as the wilderness-sustaining Rock, the Cloud-and-Fire pillar, the Manna. Athanasius&#x27;s Old-Testament-Christology runs on Pauline-1 Cor 10 + Jn 8:58 + Ex 3:14 (Burning Bush) lines. Tewahedo lectionary-pairing reads 1 Cor 10:1-4 with Ex 17:6 (Massah-Meribah) at every Tǝmqät (Theophany) anniversary baptismal-renewal.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
