        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos II.16</em> <small>(c. 350 AD)</small><p>&#x27;After the same manner also he took the cup, when he had supped, saying, This cup is the new testament in my blood: this do ye, as oft as ye drink it, in remembrance of me&#x27; — Athanasius marks hē kainē diathēkē en tō emō haimati (the new covenant in my blood) as the Pauline-institution-text that authorizes the Eucharistic-Anaphora across the whole Church. The blood-covenant-language (Ex 24:8 echo) names the Eucharist as the new-Sinai-event the Word&#x27;s-incarnation establishes. Tewahedo Anaphora-of-the-Apostles cites 1 Cor 11:23-26 at the institution-recital before every consecration.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
