        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §10</em> <small>(c. 350 AD)</small><p>&#x27;For since by man came death, by man came also the resurrection of the dead&#x27; — Athanasius marks the parallel di&#x27; anthrōpou thanatos / di&#x27; anthrōpou anastasis (through man death / through man resurrection) as the Pauline-soteriological-symmetry the entire De Incarnatione reconstructs. The Adam-Christ Pauline parallel is not merely-decorative: it grounds the soteriological-NECESSITY of the incarnation. Only a genuine-man (sharing Adam&#x27;s nature) can be the agent of resurrection-for-Adam&#x27;s-race; only a divine-Word (with power over death) can effectively rise. The incarnate-Word is both. Tewahedo paschal-doctrine cites 1 Cor 15:21-22 at the Easter-vigil kerygmatic-anchor.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
